/* Flood-fills the human's current terminal component and moves toward a
   deterministic interior cell maximizing minimum distance from all pets. */
char move_to_best_terminal_component(const HumanInfo& human,
                                     const std::vector<Point>& tentative_walls) {
    bool blocked[GRID_SIZE + 1][GRID_SIZE + 1] = {};
    for (const Point& wall : tentative_walls) {
        if (is_valid_point(wall)) blocked[wall.r][wall.c] = true;
    }

    if (!is_valid_point(human.pos) ||
        is_impassable_grid_static[human.pos.r][human.pos.c] ||
        blocked[human.pos.r][human.pos.c]) {
        return '.';
    }

    bool seen[GRID_SIZE + 1][GRID_SIZE + 1] = {};
    std::vector<Point> component;
    std::queue<Point> q;
    q.push(human.pos);
    seen[human.pos.r][human.pos.c] = true;

    while (!q.empty()) {
        Point cur = q.front();
        q.pop();
        component.push_back(cur);

        for (int d = 0; d < 4; ++d) {
            Point nxt = {cur.r + DIRS[d].r, cur.c + DIRS[d].c};
            if (!is_valid_point(nxt) ||
                seen[nxt.r][nxt.c] ||
                is_impassable_grid_static[nxt.r][nxt.c] ||
                blocked[nxt.r][nxt.c]) {
                continue;
            }
            seen[nxt.r][nxt.c] = true;
            q.push(nxt);
        }
    }

    if (component.empty()) return '.';

    Point target = component.front();
    int best_clearance = -1;
    int best_center_distance = INF;

    int center_r = (human.inner_safe_ul.r + human.inner_safe_br.r) / 2;
    int center_c = (human.inner_safe_ul.c + human.inner_safe_br.c) / 2;

    for (const Point& cell : component) {
        int clearance = INF;
        for (const PetInfo& pet : pets_global_state) {
            clearance = std::min(clearance, manhattan_distance(cell, pet.pos));
        }

        int center_distance =
            std::abs(cell.r - center_r) + std::abs(cell.c - center_c);

        if (clearance > best_clearance ||
            (clearance == best_clearance &&
             (center_distance < best_center_distance ||
              (center_distance == best_center_distance && cell < target)))) {
            best_clearance = clearance;
            best_center_distance = center_distance;
            target = cell;
        }
    }

    return get_bfs_move_char(human.pos, target, tentative_walls);
}

